// Mock exam pool, set 2. Data only; ids key saved stats, never rename or reuse.
window.QUIZ.push(
{id:"m2-001", day:"mock", dom:1, tags:["CloudFront","Load balancing"],
 q:"A company serves its web application through an Amazon CloudFront distribution protected by AWS WAF, in front of an internet-facing Application Load Balancer. A penetration test found that attackers can bypass CloudFront and WAF by sending requests straight to the ALB's public DNS name. The company now requires that the ALB have no internet exposure at all and receive traffic only through CloudFront, with the least ongoing maintenance. Which solution meets these requirements?",
 o:["Keep the ALB internet-facing and allow only the CloudFront origin-facing managed prefix list in its security group.",
    "Keep the ALB internet-facing and add a WAF rule on it that blocks requests without a CloudFront Via header.",
    "Re-create the ALB as an internal load balancer in private subnets and add it to the distribution as a VPC origin.",
    "Put the ALB behind an AWS Global Accelerator accelerator and point the CloudFront distribution at the accelerator."],
 a:[2],
 x:["The prefix list admits all of CloudFront's origin-facing servers, not only requests from this distribution, and the ALB remains internet-facing, which the requirement rules out.",
    "Request headers such as Via are easy to forge, and the ALB stays reachable from the internet, so its exposure is not removed.",
    "CloudFront VPC origins let a distribution reach an internal ALB in private subnets, so the ALB has no public endpoint and receives traffic only from distributions configured with that VPC origin.",
    "Global Accelerator gives the application public static IP addresses, which adds internet exposure instead of removing it."],
 ref:["d8e3","d10c1"], doc:"cloudfront"},
{id:"m2-002", day:"mock", dom:2, tags:["API Gateway"],
 q:"A logistics company exposes a REST API in Amazon API Gateway that 40 partners call to create shipment requests. The backend is a fleet of EC2 instances that can process about 500 requests per second; above that, errors cascade. Last week one partner sent a burst that exceeded this rate and caused failures for every partner. The company wants each partner held to its contracted rate and burst, excess requests rejected with HTTP 429 so that partners retry, and no changes to the backend. Which solution meets these requirements?",
 o:["Enable API Gateway caching on the production stage with a 300-second TTL so repeated shipment requests skip the backend.",
    "Create usage plans with per-partner rate and burst limits and API keys, and set stage throttling below backend capacity.",
    "Associate an AWS WAF web ACL with the stage and add a rate-based rule that blocks IP addresses exceeding the backend limit.",
    "Integrate API Gateway directly with an SQS queue and have the EC2 instances poll the queue at their own pace."],
 a:[1],
 x:["Shipment creation is a state-changing POST, so its responses must not be cached and replayed to other callers, and caching does not limit how fast a partner sends requests.",
    "Usage plans apply token-bucket rate and burst limits per API key, so one partner cannot consume another's capacity, and API Gateway returns 429 Too Many Requests for excess calls. Stage-level throttling caps the total below what the backend can handle. AWS applies these limits on a best-effort basis.",
    "Rate-based rules count requests per IP address or other aggregation key over a window of at least one minute, so they cannot enforce a per-partner, per-second rate and burst; a partner that sends from many IP addresses also slips through.",
    "Queueing changes how the backend receives work (it must poll SQS instead of serving HTTP) and partners lose their synchronous response, which violates the no-backend-changes requirement."],
 ref:["d9e2","d10b2"], doc:"apigw"},
{id:"m2-003", day:"mock", dom:3, tags:["S3 features"],
 q:"A genomics lab writes 2–4 GB result files from EC2 instances to an S3 bucket in the same Region using single PUT requests. Uploads are slow and occasionally fail near the end, forcing a full retry. A fleet of analysis workers then reads small index objects, all stored under one prefix, at a combined rate of about 30,000 GET requests per second, and many requests return HTTP 503 Slow Down errors. Which combination of actions will improve performance? (Choose two.)",
 o:["Enable S3 Transfer Acceleration on the bucket and upload through the accelerate endpoint.",
    "Upload the result files with multipart upload, sending parts in parallel and retrying only failed parts.",
    "Use byte-range GET requests when the workers read the small index objects.",
    "Spread the index objects across many prefixes, for example by adding a hash-based prefix to each key.",
    "Enable S3 Versioning so that interrupted uploads can resume from the last stored version."],
 a:[1,3],
 x:["Transfer Acceleration is designed for transfers over long distances through CloudFront edge locations; these instances are already in the bucket's Region, and a failed single PUT would still restart from zero.",
    "Multipart upload sends parts concurrently for higher throughput, and a failed part is retried on its own instead of restarting the whole file. AWS recommends it for objects larger than about 100 MB.",
    "Byte-range fetches help parallelize downloads of large objects; for small index objects they only add requests, which makes the per-prefix 503 throttling worse.",
    "S3 supports about 5,500 GET/HEAD requests per second per partitioned prefix, so 30,000 per second against one prefix triggers 503 errors. Spreading keys across prefixes lets S3 scale request capacity in parallel.",
    "Versioning keeps earlier versions of complete objects; it has no concept of resuming a partial upload and does nothing for request-rate throttling."],
 ref:["d10e2","d3w1"], doc:"s3"},
{id:"m2-004", day:"mock", dom:4, tags:["Aurora"],
 q:"Every Monday, a company's QA team restores the latest snapshot of its 8 TB production Amazon Aurora PostgreSQL cluster five times to create separate, writable test databases for five test teams. Each restore takes several hours, and the company pays for five full copies of the storage even though each team changes less than 2% of the data during the week. The company wants writable test copies that are ready faster, at the lowest storage cost. Which solution meets these requirements?",
 o:["Add five Aurora Replicas to the production cluster and give each test team the endpoint of one of the replicas.",
    "Create five Aurora clones of the production cluster each Monday and give one clone to each of the test teams.",
    "Restore the snapshots into Aurora serverless clusters with a low minimum capacity for each of the test teams.",
    "Add an Aurora Global Database secondary cluster in another Region and let the test teams share it for testing."],
 a:[1],
 x:["Aurora Replicas are read-only and belong to the production cluster, so the test teams could not write test data.",
    "Aurora cloning uses a copy-on-write protocol: a clone is created quickly without copying the data, and additional storage is allocated only as the source or the clone changes data.",
    "Aurora serverless (formerly Aurora Serverless v2) can lower compute cost, but each restore still copies the full 8 TB volume and still takes hours.",
    "A Global Database secondary cluster is read-only and pays for a full copy of the storage plus replication, so it meets neither need."],
 ref:["d11e4","d3w2"], doc:"aurora"},
{id:"m2-005", day:"mock", dom:1, tags:["KMS & encryption","IAM policies"],
 q:"A healthcare company encrypts patient records in Amazon S3 with an AWS KMS customer managed key. Auditors require separation of duties in the key policy: the security team's KeyAdmin role must be able to administer the key, such as enabling rotation, disabling the key, and scheduling deletion, but must not be granted any permission to use the key for cryptographic operations. The application's AppRole must be able to encrypt and decrypt data but must not be able to administer the key. Which combination of key policy statements meets these requirements? (Choose two.)",
 o:["Allow the KeyAdmin role <code>kms:*</code> on the key so that it can step in if the application role is ever deleted.",
    "Allow the KeyAdmin role only administrative actions, such as <code>kms:EnableKeyRotation</code> and <code>kms:ScheduleKeyDeletion</code>.",
    "Allow the AppRole <code>kms:*</code> on the key so that the application can rotate the key itself when auditors ask.",
    "Allow the AppRole only <code>kms:Encrypt</code>, <code>kms:Decrypt</code>, <code>kms:ReEncrypt*</code>, and <code>kms:GenerateDataKey*</code>.",
    "Allow the KeyAdmin role <code>kms:Decrypt</code> with a condition that requires MFA, so that it is used only in emergencies."],
 a:[1,3],
 x:["<code>kms:*</code> includes <code>kms:Decrypt</code> and every other cryptographic action, so the KeyAdmin role could read patient data, which breaks separation of duties.",
    "Granting only administrative actions lets the security team manage the key's lifecycle without any cryptographic permission; this is the key administrator pattern in KMS key policies.",
    "<code>kms:*</code> would let the application role disable, change, or schedule deletion of the key, which the auditors prohibit.",
    "A key user statement with only cryptographic actions lets the application encrypt and decrypt, while administrative actions stay with the security team.",
    "An MFA condition limits when decryption happens, but it still grants the KeyAdmin role a cryptographic permission, which the requirement forbids."],
 ref:["d8e4","d4b4","d4c1"], doc:"kms"},
{id:"m2-006", day:"mock", dom:2, tags:["Streaming","Lambda"],
 q:"A payments company processes transaction events from an Amazon Kinesis data stream with a Lambda function through an event source mapping. Occasionally a malformed record makes the function throw an error, and Lambda keeps retrying the same batch until the records expire, so processing for that shard stops and the consumer falls hours behind. The company wants the shard to keep moving, the failing record isolated from the valid records in its batch, and the location of each discarded record kept for later investigation. The function code must not change. Which solution meets these requirements?",
 o:["Enable batch bisection, a maximum retry count, and an on-failure SQS destination on the event source mapping.",
    "Attach an SQS dead-letter queue to the Kinesis data stream with a redrive policy that has a maxReceiveCount of 3.",
    "Increase the number of shards in the stream so that the malformed record blocks a smaller share of the events.",
    "Increase the function's timeout to 15 minutes and raise its memory so that each batch has more time to finish."],
 a:[0],
 x:["Bisection splits a failing batch so the valid records are processed and the bad record is isolated, the retry limit stops endless retries so the shard moves on, and the on-failure destination receives details of the discarded records, such as the shard ID and sequence numbers.",
    "Kinesis data streams have no dead-letter queues or redrive policies; those belong to SQS queues, and failure handling for stream consumers is configured on the event source mapping.",
    "More shards spread new records out, but the shard that holds the malformed record is still blocked by endless retries.",
    "The failure comes from bad data, not from a lack of time or memory, so the batch would keep failing and being retried."],
 ref:["d9e2","d6c3"], doc:"lambda"},
{id:"m2-007", day:"mock", dom:3, tags:["DynamoDB"],
 q:"An IoT platform writes about 10,000 device readings per second to a DynamoDB table in on-demand mode with <code>deviceId</code> as the partition key. To find readings that need review, the team added a global secondary index with <code>status</code> as its partition key; status has three values, and nearly every item is OK. Since the index was added, writes to the base table are throttled even though the table is far below its own limits. Which change resolves the throttling while still allowing efficient queries by status?",
 o:["Switch the table and index to provisioned capacity with auto scaling and a higher maximum write capacity.",
    "Add a DynamoDB Accelerator (DAX) cluster in front of the table to absorb the write traffic.",
    "Replace the global secondary index with a local secondary index whose sort key is <code>status</code>.",
    "Make the index partition key the status plus a random suffix from 0 to 19, and query all suffixes in parallel."],
 a:[3],
 x:["Throughput for a single partition key value is capped per partition in either capacity mode, so the OK key stays hot; more provisioned capacity does not spread it.",
    "DAX is a read-through and write-through cache; every write still goes to the table and its indexes, so it cannot relieve write throttling.",
    "An LSI can only be created with the table and shares the base partition key, so it finds statuses within one device rather than across all devices, and it adds a 10 GB limit per partition key value.",
    "A low-cardinality GSI key concentrates writes on one partition, and a throttled GSI back-pressures writes to the base table. Write sharding spreads each status across many key values; readers query the shards in parallel and merge the results."],
 ref:["d10e4","d3b3"], doc:"dynamodb"},
{id:"m2-008", day:"mock", dom:1, tags:["Instance access"],
 q:"During a security investigation, a company must run a script that collects running processes, open network connections, and recent logins from 400 Linux EC2 instances tagged <code>Environment=Prod</code>. The instances are in private subnets with Systems Manager interface endpoints, run the SSM Agent with an instance profile, and allow no inbound connections. The script must run on no more than 10% of the instances at a time and stop if more than 5 instances fail, every invocation must be authorized through IAM, and the output must be saved to Amazon S3. Which solution meets these requirements with the least operational overhead?",
 o:["Open a Session Manager session to each instance in turn, paste the script, and upload the output to S3 afterward.",
    "Create an EC2 Instance Connect Endpoint and loop over the instances with an SSH script that copies output to S3.",
    "Add the script to the launch template's user data and replace the instances so that each one runs it at boot.",
    "Use Systems Manager Run Command on the tagged instances, with concurrency and error limits and output to S3."],
 a:[3],
 x:["Session Manager is built for interactive sessions, so running the script on 400 instances one by one is slow manual work; concurrency and error thresholds are Run Command settings.",
    "SSH through an Instance Connect Endpoint requires inbound port 22 on the instances, which the company does not allow, and the loop is custom tooling to maintain.",
    "User data runs only at launch, and replacing production instances during an investigation would destroy the evidence that the script must collect.",
    "Run Command runs a document on instances selected by tag through the SSM Agent's outbound connection, enforces maximum concurrency and error thresholds, authorizes each command with IAM, and can write the output to S3."],
 ref:["d8e3","d2b3"], doc:"ssm"},
{id:"m2-009", day:"mock", dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A video platform stores master files in S3 Standard and generates lower-resolution renditions of each video, typically 100 MB to 2 GB each, also in S3 Standard. After 30 days, each rendition is requested about once a month and must still start streaming within milliseconds. Renditions can be regenerated from the masters in minutes, so the company accepts losing them if an Availability Zone is destroyed. Which lifecycle action for renditions older than 30 days is the MOST cost-effective?",
 o:["Transition the renditions to S3 One Zone-Infrequent Access.",
    "Transition the renditions to S3 Standard-Infrequent Access.",
    "Transition the renditions to S3 Glacier Flexible Retrieval.",
    "Transition the renditions to S3 Glacier Instant Retrieval."],
 a:[0],
 x:["One Zone-IA keeps millisecond access at a lower storage price than Standard-IA by storing data in a single AZ, which is acceptable for data that can be re-created. Objects this large are unaffected by the 128 KB minimum billable size.",
    "Standard-IA also gives millisecond access, but it pays for multi-AZ resilience that the company explicitly does not need for re-creatable renditions.",
    "Glacier Flexible Retrieval requires a restore that takes minutes to hours, so renditions could not start streaming within milliseconds.",
    "Glacier Instant Retrieval is designed for data read about once a quarter; with monthly reads, its higher per-GB retrieval charge outweighs its lower storage price."],
 ref:["d11e2","d3c3"], doc:"s3-classes"},
{id:"m2-010", day:"mock", dom:2, tags:["SQS"],
 q:"An insurance company processes claim documents with workers in an Auto Scaling group that poll an Amazon SQS standard queue. Each message takes 2 to 6 minutes to process, and workers delete the message when they finish. The queue was created with default settings. Many claims are processed two or three times, causing duplicate payouts, although the workers are healthy and complete every job. Which change will MOST effectively reduce the duplicate processing?",
 o:["Recreate the queue as a FIFO queue with content-based deduplication enabled.",
    "Enable long polling by setting the receive message wait time to 20 seconds.",
    "Configure a dead-letter queue with a maximum receive count of 1.",
    "Raise the visibility timeout above the longest expected processing time."],
 a:[3],
 x:["FIFO deduplication only drops duplicate sends within a 5-minute window; a message whose visibility timeout expires before it is deleted is still delivered again.",
    "Long polling reduces empty responses and API cost; it does not change how long a received message stays hidden from other workers.",
    "This hides the symptom by moving any message received twice to the dead-letter queue, which leaves valid claims unprocessed and does not fix the root cause.",
    "The default 30-second visibility timeout expires while workers are still processing, so other workers receive the same message. A timeout above the processing time (extended with ChangeMessageVisibility for unusually long jobs) prevents redelivery; consumers should still be idempotent."],
 ref:["d9e2","d9c1"], doc:"sqs"},
{id:"m2-011", day:"mock", dom:1, tags:["Security groups & NACLs"],
 q:"A company runs internet-facing APIs in 15 AWS accounts in AWS Organizations, and each account's application team manages its own security groups. Every API security group must allow HTTPS only from the same set of 30 partner CIDR ranges. Partners add or retire ranges several times a month, and the security team currently edits hundreds of security group rules by hand and often misses some. The security team wants to maintain the partner ranges in one place and have every referencing security group pick up changes automatically, with no custom code. Which solution meets these requirements?",
 o:["Add the partner CIDRs as allow rules to the network ACLs of every API subnet, and keep them current with a shared runbook.",
    "Reference the AWS-managed prefix list for the Region in each security group so that AWS keeps the partner ranges current.",
    "Create a customer-managed prefix list of the partner CIDRs, share it with AWS RAM, and reference it in security groups.",
    "Write a Lambda function that copies the rules from a master security group to every account's security groups on a schedule."],
 a:[2],
 x:["Network ACLs are separate for each subnet in every account, so the ranges would still be edited in many places, and a runbook is the manual process the team wants to replace.",
    "AWS-managed prefix lists contain the address ranges of AWS services such as S3, DynamoDB, and CloudFront; they cannot hold a company's partner ranges.",
    "A customer-managed prefix list keeps the CIDRs in one place, AWS RAM shares it with the other accounts, and every security group rule that references it uses the updated entries as soon as the list changes.",
    "A scheduled copy function is custom code to build and maintain, and changes would apply only on its next run."],
 ref:["d8e3","d2c1"], doc:"vpc"},
{id:"m2-012", day:"mock", dom:3, tags:["CloudFront"],
 q:"A media company serves its website through Amazon CloudFront at peaks of several hundred thousand requests per second. On every viewer request, it must rewrite the URL (lowercase the path and append index.html to directory paths) and redirect visitors to a country-specific path based on the CloudFront-Viewer-Country header. The logic is a few lines of JavaScript, needs no network calls or access to the request body, and must add less than a millisecond of latency at the lowest cost. Which solution meets these requirements?",
 o:["Deploy a CloudFront Function on the viewer request event of the cache behavior.",
    "Deploy a Lambda@Edge function on the viewer request event of the cache behavior.",
    "Deploy a Lambda@Edge function on the origin request event of the cache behavior.",
    "Send all requests to an ALB origin where a Lambda function rewrites and redirects them."],
 a:[0],
 x:["CloudFront Functions run lightweight JavaScript at every edge location with sub-millisecond execution, scale to millions of requests per second, and cost a fraction of Lambda@Edge. The function can read CloudFront-Viewer-Country once that header is included in the behavior's origin request or cache policy.",
    "Lambda@Edge would work functionally, but it runs in Regional edge caches with millisecond-level execution and costs more per request, so it misses the sub-millisecond and lowest-cost requirements.",
    "Origin request functions run only on cache misses, so cached responses would skip the rewrite and per-country redirect logic, and Lambda@Edge still costs more.",
    "Sending every request to the origin gives up edge caching and adds round-trip latency far above a millisecond."],
 ref:["d10e5","d10b1"], doc:"cloudfront"},
{id:"m2-013", day:"mock", dom:2, tags:["EFS","High availability design"],
 q:"A news website runs a content management system on EC2 instances in an Auto Scaling group across three Availability Zones behind an ALB. Editors upload images that the CMS writes to <code>/var/www/uploads</code> on the local disk and later reads back by file path. Readers often see broken images when another instance serves the page, and images are lost when instances are terminated. The CMS cannot be modified to use an object storage API. Which solution meets these requirements?",
 o:["Attach one io2 EBS volume with Multi-Attach enabled to every instance and mount it at the uploads path.",
    "Enable sticky sessions on the ALB target group so that each user keeps reaching the same instance.",
    "Mount an Amazon EFS file system with mount targets in each Availability Zone at the uploads path.",
    "Run a cron job on each instance that synchronizes the uploads directory with an S3 bucket every minute."],
 a:[2],
 x:["EBS Multi-Attach works only for instances in the same Availability Zone and needs a cluster-aware file system, so it cannot serve an Auto Scaling group spread across three AZs.",
    "Stickiness keeps one user on one instance, but other readers still reach instances without the file, and uploads still disappear when an instance is terminated.",
    "EFS is a POSIX file system that instances in multiple AZs mount concurrently, and it stores data redundantly across AZs, so every instance sees the same files and nothing is lost when instances are replaced.",
    "Periodic sync leaves windows in which files are missing, can conflict when several instances write, and still risks losing files written just before an instance terminates."],
 ref:["d9e3","d3p3"], doc:"efs"},
{id:"m2-014", day:"mock", dom:1, tags:["Encryption in transit","Load balancing"],
 q:"A company runs dozens of internal microservices behind internal Application Load Balancers. The services use host names in a private domain, such as orders.corp.internal, that resolves only inside the company's network. Security requires TLS on every connection, with certificates that company-managed devices trust, that renew automatically, and that are managed centrally in AWS. Which solution meets these requirements with the least operational overhead?",
 o:["Request public certificates from AWS Certificate Manager for each host name and validate them with DNS records.",
    "Generate self-signed certificates for each service with OpenSSL and import them into AWS Certificate Manager.",
    "Buy certificates for each host name from a commercial public certificate authority and import them into ACM.",
    "Create a private CA in AWS Private CA and issue private certificates through ACM for the internal ALBs."],
 a:[3],
 x:["ACM issues a public certificate only after validating control of the domain, and DNS validation requires records that resolve over the public internet, so names in a private domain such as corp.internal cannot be validated.",
    "Self-signed certificates are not trusted by company devices unless each one is distributed manually, and ACM does not renew imported certificates.",
    "Public certificates are limited to identifying resources with public DNS names, so a public CA is the wrong source for names in a private domain, and ACM does not renew imported certificates.",
    "AWS Private CA creates a company-owned CA whose root the devices can trust; ACM issues private certificates from it, deploys them to the ALBs, and renews them automatically."],
 ref:["d8e4","d8c3"], doc:"acm"},
{id:"m2-015", day:"mock", dom:4, tags:["FSx"],
 q:"A company is migrating 60 TB of Windows department shares and user home directories to Amazon FSx for Windows File Server. The shares must stay available if an Availability Zone fails. Performance needs are modest, and an analysis shows that many files are duplicated across departments. The company wants the lowest storage cost. Which combination of actions meets these requirements? (Choose two.)",
 o:["Create a Multi-AZ file system that uses the HDD storage type.",
    "Create a Single-AZ file system that uses the SSD storage type.",
    "Provision the highest throughput capacity so that files open faster.",
    "Store the shares on Amazon FSx for Lustre linked to an S3 bucket.",
    "Enable data deduplication on the file system after the migration."],
 a:[0,4],
 x:["HDD storage costs much less per GB than SSD and suits general-purpose shares and home directories with modest performance needs, and Multi-AZ keeps the shares available if an AZ fails.",
    "Single-AZ does not survive an AZ failure, and SSD storage costs more per GB than this workload needs.",
    "Higher throughput capacity raises cost without being needed for modest performance, and it does not reduce the amount of stored data.",
    "FSx for Lustre is a high-performance file system that Linux clients mount with the Lustre client over its own protocol rather than SMB, so it does not fit Windows department shares.",
    "Data deduplication stores duplicate file content only once, which typically saves a large share of capacity on general-purpose file shares and lowers storage cost."],
 ref:["d11e2","d3c1"], doc:"fsx-windows"},
{id:"m2-016", day:"mock", dom:1, tags:["Cognito","S3 security"],
 q:"A fitness startup's mobile app lets users sign in with Apple, with Google, or with a username and password stored in an Amazon Cognito user pool. After signing in, the app must upload workout videos directly to Amazon S3 under a prefix unique to each user, without routing the files through the company's backend and without embedding long-term credentials in the app. Which solution meets these requirements?",
 o:["Send the user pool ID token in the Authorization header of S3 PutObject requests so that S3 can validate the user.",
    "Create an IAM user for each app user at sign-up and store the access keys in the device's secure storage.",
    "Use a Cognito identity pool to exchange the sign-in token for temporary credentials limited to the user's prefix.",
    "Add a bucket policy that names the Cognito user pool as the principal and allows PutObject for its users."],
 a:[2],
 x:["AWS API requests, including S3 uploads, are authenticated by a Signature Version 4 signature made with AWS credentials; a user pool token is not such a credential and must first be exchanged for one.",
    "Per-user IAM users put long-term access keys on devices and do not scale; IAM also limits the number of users per account.",
    "Identity pools federate the user pool and social identity providers and issue temporary AWS credentials for an IAM role. A policy variable such as <code>${cognito-identity.amazonaws.com:sub}</code> in the resource ARN limits each user to their own prefix.",
    "A user pool is not an IAM principal, so it cannot be named in a bucket policy, and callers still need AWS credentials to sign requests."],
 ref:["d8e3","d8c1"], doc:"cognito"},
{id:"m2-017", day:"mock", dom:2, tags:["Disaster recovery","DynamoDB"],
 q:"A global payments company requires its transaction API to keep serving customers with an RTO of nearly zero and an RPO of seconds, even if an entire AWS Region fails. Customers are in North America and Europe and must be served from the closest healthy Region during normal operation. The API runs in containers and stores its state in DynamoDB. Which disaster recovery strategy meets these requirements?",
 o:["Warm standby: a scaled-down stack in a second Region, a DynamoDB global table, and Route 53 failover routing.",
    "Multi-site active/active: full stacks in two Regions, a DynamoDB global table, and latency routing with health checks.",
    "Pilot light: core infrastructure in a second Region, with DynamoDB point-in-time recovery used to restore the table.",
    "Backup and restore: on-demand DynamoDB backups copied to a second Region by AWS Backup and restored with IaC."],
 a:[1],
 x:["Warm standby leaves one Region serving all traffic and needs a scale-up and DNS failover during a disaster, so the RTO is minutes rather than near zero, and users are not served from the closest Region.",
    "Both Regions serve production traffic all the time, global tables typically replicate writes within a second, and latency routing with health checks sends users to the nearest healthy Region, so losing a Region causes almost no downtime.",
    "Pilot light requires scaling out the application and restoring the table during a disaster, which takes tens of minutes or more, far from a near-zero RTO and an RPO of seconds.",
    "Backup and restore has the longest RTO (hours) and an RPO equal to the backup interval, which fails both objectives."],
 ref:["d9e3","d9c2","d9c4"], doc:"dynamodb"},
{id:"m2-018", day:"mock", dom:3, tags:["Caching"],
 q:"A news aggregator renders HTML fragments from an Amazon RDS for PostgreSQL database and wants to cache them to cut database load. The fragments are simple string values that can be regenerated at any time, so losing cached data when a node fails is acceptable. The cache must scale horizontally by adding nodes and must make use of many CPU cores on each node. Persistence, replication, pub/sub, and rich data types are not needed. Which solution meets these requirements with the simplest design?",
 o:["Amazon ElastiCache for Memcached with several nodes and auto discovery in the client.",
    "Amazon ElastiCache for Redis OSS with Multi-AZ replicas and daily snapshots enabled.",
    "DynamoDB Accelerator (DAX) placed between the application and the database.",
    "Amazon MemoryDB with a multi-shard cluster and a transaction log for durability."],
 a:[0],
 x:["Memcached is a simple, multithreaded key-value cache that uses multiple cores per node and scales out by adding nodes, with nodes that clients find through auto discovery; it has no native replication or failover, which this workload does not need.",
    "Redis OSS would work, but replicas and snapshots add cost and complexity the workload explicitly does not need; Memcached is the simpler fit for a plain multithreaded cache.",
    "DAX caches only DynamoDB API calls; it cannot sit in front of an RDS for PostgreSQL database.",
    "MemoryDB is a durable, Redis-compatible primary database; paying for durability and a transaction log is unnecessary for cache entries that can be regenerated."],
 ref:["d10e4","d10c2"], doc:"elasticache"},
{id:"m2-019", day:"mock", dom:1, tags:["Lambda","IAM roles & cross-account"],
 q:"A media company's ingest pipeline runs on Amazon ECS tasks in Account A. A thumbnail-transcoding Lambda function runs in Account B. The ECS tasks must invoke the function synchronously. The Account B team wants to control, on the function itself, which external callers can invoke it, and it does not want to create or manage any IAM roles for Account A's workloads. Which solution meets these requirements?",
 o:["Create an IAM role in Account B that can invoke the function and trusts Account A, and have the tasks assume it.",
    "Share the Lambda function with Account A through AWS Resource Access Manager and invoke it by its shared ARN.",
    "Create a Lambda interface VPC endpoint in Account A with an endpoint policy that allows invoking the function.",
    "Add a function resource-based policy that allows the ECS task role, and allow the call in the role's own policy."],
 a:[3],
 x:["Role assumption works, but it requires creating and maintaining an IAM role in Account B, which the team explicitly wants to avoid.",
    "AWS RAM does not support sharing Lambda functions; cross-account invocation is granted through the function's resource-based policy.",
    "Endpoint policies can only restrict what passes through the endpoint; they cannot grant cross-account permission, so the function would still reject the call.",
    "A Lambda resource-based policy (added with <code>add-permission</code>) lets Account B grant <code>lambda:InvokeFunction</code> to a specific principal in Account A. The task role also needs an identity policy that allows the call, and no roles are created in Account B."],
 ref:["d8e2","d4c1"], doc:"lambda"},
{id:"m2-020", day:"mock", dom:4, tags:["Data transfer costs"],
 q:"A genomics company runs a self-managed processing cluster of EC2 instances split evenly across two Availability Zones in one Region. During each nightly batch, nodes exchange intermediate data with each other over their private IP addresses, about 400 TB per month in total. The batch can simply be rerun if it fails, and it does not need to survive an AZ outage mid-run. Cost Explorer shows inter-AZ data transfer as the largest line item. Which change will MOST reduce this cost?",
 o:["Have the nodes communicate through their Elastic IP addresses instead of their private addresses.",
    "Launch all cluster nodes in a single Availability Zone, using a cluster placement group.",
    "Route traffic between the two AZs through a NAT gateway in each Availability Zone.",
    "Enable enhanced networking with ENA on every node to compress traffic between AZs."],
 a:[1],
 x:["Traffic sent to public or Elastic IP addresses is charged even within the same AZ, so this raises the cost rather than lowering it.",
    "Data transferred between instances in the same AZ over private IP addresses is free, while cross-AZ traffic is charged in each direction. A restartable batch does not need multiple AZs, and a cluster placement group also improves network performance.",
    "NAT gateways add a per-GB processing charge on top of the cross-AZ transfer, so routing through them increases cost.",
    "ENA increases bandwidth and packets per second, but it does not compress data or change how inter-AZ transfer is billed."],
 ref:["d11e5","d11c3"], doc:"ec2-pricing"},
{id:"m2-021", day:"mock", dom:2, tags:["SQS","Lambda"],
 q:"A ticketing company's API Gateway API invokes Lambda functions that write purchase confirmations directly to an Amazon RDS for MySQL DB instance. During on-sale events, writes spike to about 30,000 per minute, the database runs out of connections, and some writes fail. Users do not need the write committed before they receive a response, but no write may be lost. The company does not want to scale up the database for short peaks. Which combination of steps meets these requirements? (Choose two.)",
 o:["Have the API-facing functions send each confirmation to an SQS queue and return a response immediately.",
    "Increase the reserved concurrency of the API-facing Lambda functions so that more writes run in parallel.",
    "Create an RDS read replica and direct confirmation writes to the replica during on-sale events.",
    "Consume the queue with a Lambda function whose SQS event source mapping sets a maximum concurrency the database can sustain.",
    "Add an ElastiCache cluster as a write-through cache in front of the database for the confirmation writes."],
 a:[0,3],
 x:["The queue durably absorbs the spike and decouples the API from the database, so users get an immediate response and messages wait safely (up to 14 days, depending on the retention setting) until they are written.",
    "More concurrent functions open more database connections, which makes the connection exhaustion worse.",
    "Read replicas are read-only, so they cannot accept the confirmation writes.",
    "Maximum concurrency on the event source mapping caps how many consumer functions run at once, so the database sees a steady, bounded write rate while the queue drains.",
    "A write-through cache still writes to the database synchronously on every request, so it neither buffers the spike nor reduces connections."],
 ref:["d9e2","d9b1"], doc:"sqs"},
{id:"m2-022", day:"mock", dom:1, tags:["S3 security","KMS & encryption"],
 q:"A bank's S3 bucket has default encryption set to SSE-KMS with an approved customer managed key. Security found that some upload tools set their own encryption headers and store objects with SSE-S3 or with a different KMS key, which bypasses the audit controls on the approved key. Every new object must be encrypted with the approved key, and uploads that request any other encryption must fail. Which solution meets these requirements?",
 o:["Enable S3 Bucket Keys on the bucket so that every object is encrypted with a bucket-level key from the approved key.",
    "Turn on automatic rotation for the approved key so that objects stored under other keys are re-encrypted with it.",
    "Enable S3 Object Lock in governance mode so that objects with the wrong encryption settings cannot be written.",
    "Add a bucket policy that denies s3:PutObject requests whose encryption headers name anything but the approved key."],
 a:[3],
 x:["Bucket Keys reduce KMS request costs for SSE-KMS objects; they do not stop requests that ask for SSE-S3 or for another key.",
    "Rotation changes the key material of the approved key only; it never re-encrypts objects that were stored with other keys.",
    "Object Lock prevents object versions from being deleted or overwritten; it does not check how a new object is encrypted.",
    "The S3 guide's pattern for requiring one KMS key is a Deny on <code>s3:PutObject</code> whose condition compares <code>s3:x-amz-server-side-encryption-aws-kms-key-id</code> with the approved key's ARN: the key S3 uses for the object must match it, so uploads that ask for SSE-S3 or name another key are rejected. IAM treats a negated operator such as <code>StringNotEquals</code> as true when the key is absent from the request, so test uploads that send no encryption headers; they may be denied instead of falling back to the bucket default."],
 ref:["d8e4","d4c1"], doc:"s3"},
{id:"m2-023", day:"mock", dom:3, tags:["Streaming","Analytics"],
 q:"A ride-sharing company streams vehicle telemetry into an Amazon Kinesis data stream. It needs to compute rolling 1-minute averages of speed and demand per city, detect anomalies against those windows, and update an operations dashboard within seconds of each event. The team wants a managed service that handles state, checkpointing, and scaling, and it does not want to manage clusters. Which solution meets these requirements?",
 o:["Run an Amazon Managed Service for Apache Flink application that reads the stream and computes windowed aggregates.",
    "Deliver the stream to S3 with Amazon Data Firehose and run Athena queries on the newly written objects every minute.",
    "Run a nightly AWS Glue Spark job that reads the stream's retained records and writes the aggregates to Amazon S3.",
    "Run a long-lived Amazon EMR cluster with Spark Streaming on EC2 instances that the team patches and scales."],
 a:[0],
 x:["Managed Service for Apache Flink runs stateful stream processing with windowed aggregations, checkpoints, and automatic scaling, producing results within seconds without clusters to manage.",
    "Firehose delivers buffered batches of records to S3, and a query that runs once a minute sees only files that have already landed, so the dashboard trails the events, and nothing in this design keeps windowed state or checkpoints.",
    "A nightly batch job produces results hours after the events, not within seconds.",
    "Spark Streaming on EMR could process the stream, but the team would have to manage, patch, and scale the cluster, which it wants to avoid."],
 ref:["d10e6","d10c3"], doc:"flink"},
{id:"m2-024", day:"mock", dom:2, tags:["DynamoDB","High availability design"],
 q:"A travel booking site runs on EC2 instances in an Auto Scaling group behind an ALB with sticky sessions. Shopping carts are held in instance memory, so users lose them when instances are scaled in or fail, and new instances receive little traffic. The company wants stateless web instances, carts that persist for up to 7 days and survive an Availability Zone failure, single-digit millisecond reads and writes, and no servers to manage for the session store. Which solution meets these requirements?",
 o:["Store carts in a node-based ElastiCache for Memcached cluster and disable sticky sessions on the target group.",
    "Increase the stickiness duration to 7 days so that each user always returns to the same instance.",
    "Store carts as objects in an S3 bucket keyed by session ID with a lifecycle rule that expires them after 7 days.",
    "Store carts in a DynamoDB table keyed by session ID with a TTL attribute, and disable sticky sessions."],
 a:[3],
 x:["A node-based Memcached cluster keeps data only in memory without replication, so a node or AZ failure loses carts, the cache may evict them before 7 days, and the nodes are still servers to size and manage.",
    "Longer stickiness does not help when the instance is terminated, and it worsens load imbalance as the group scales.",
    "S3 is serverless and durable, but AWS describes small-object latencies of roughly 100–200 milliseconds for it, which misses the single-digit millisecond requirement.",
    "DynamoDB is serverless, replicates across three AZs, and delivers single-digit millisecond access; TTL expires carts after 7 days at no cost, and any instance can serve any request."],
 ref:["d9e2","d3c4"], doc:"dynamodb"},
{id:"m2-025", day:"mock", dom:1, tags:["S3 security"],
 q:"After a developer exposed sensitive data by adding a public-read ACL to an object, a company's security team must guarantee that no S3 bucket or object in its production account, existing or created in the future, can be made public through ACLs or bucket policies, even if someone changes an individual bucket's settings. Some buckets are served only through CloudFront with origin access control. Which solution meets these requirements with the LEAST effort?",
 o:["Enable all four S3 Block Public Access settings at the account level for the production account.",
    "Enable Block Public Access on each existing bucket and use an EventBridge rule to enable it on new buckets.",
    "Deploy the AWS Config rule that detects public buckets and attach an automatic remediation action.",
    "Enable Amazon Macie to scan the buckets daily and alert the team when a bucket becomes public."],
 a:[0],
 x:["S3 applies the most restrictive combination of account- and bucket-level settings, so account-level Block Public Access blocks public ACLs and policies for every current and future bucket regardless of bucket settings. OAC grants access to the CloudFront service principal, which is not public access.",
    "Bucket-level settings can be turned off by anyone with permission on that bucket, and the automation adds moving parts; the account-level setting covers everything in one step.",
    "Config detects and fixes public buckets after the change, leaving a window of exposure instead of preventing it.",
    "Macie discovers sensitive data and reports on bucket exposure, but it only alerts; it does not prevent buckets from becoming public."],
 ref:["d8e4","d3b1"], doc:"s3"},
{id:"m2-026", day:"mock", dom:4, tags:["EC2 purchase options","Auto Scaling"],
 q:"A video-rendering company runs stateless, fault-tolerant render workers in an Auto Scaling group that uses only Spot Instances of a single instance type with the lowest-price allocation strategy. Workers are interrupted frequently, and the group sometimes cannot launch capacity, which delays customer jobs. The workers can run on any current-generation compute-optimized or general-purpose instance type with at least 16 vCPUs. The company wants as few interruptions as possible while keeping compute costs low. Which solution BEST meets these requirements?",
 o:["Keep the single instance type and set the maximum Spot price equal to the On-Demand price.",
    "Use a mixed instances policy with many eligible types across all AZs and the price-capacity-optimized strategy.",
    "Use a mixed instances policy with many eligible types across all AZs and keep the lowest-price strategy.",
    "Purchase Reserved Instances for the instance type to cover the average number of render workers."],
 a:[1],
 x:["A Spot request is already capped at the On-Demand price by default, and AWS notes that instances with a specified maximum price are interrupted more often; the interruptions here come from EC2 reclaiming capacity in a single pool, which a price setting does not fix.",
    "Diversifying across many instance types and AZs opens more Spot capacity pools, and price-capacity-optimized chooses pools with the most spare capacity at low prices, which is the recommended way to cut interruptions while keeping Spot savings.",
    "Diversification helps, but lowest-price keeps choosing the cheapest pools regardless of spare capacity, and those are often the pools interrupted most.",
    "Reserved Instances bill around the clock and cost far more than Spot for interruptible batch work whose size fluctuates."],
 ref:["d11e3","d11c2"], doc:"autoscaling"},
{id:"m2-027", day:"mock", dom:3, tags:["Redshift","Analytics"],
 q:"A central data engineering team loads curated sales data into an Amazon Redshift RA3 provisioned cluster every 15 minutes. A finance analytics team in another AWS account now needs to query that data, including the latest loads, from its own Amazon Redshift Serverless workgroup so that its heavy queries never consume the producer cluster's resources. The company does not want to copy or unload data or build new pipelines. Which solution meets these requirements?",
 o:["Create a datashare on the producer cluster and grant it to the finance account for its Serverless workgroup.",
    "Unload the sales tables to S3 every 15 minutes and have the finance team query them with Redshift Spectrum.",
    "Restore the latest automated snapshot of the producer cluster into the finance account every 15 minutes.",
    "Create database users for the finance team on the producer cluster and enable concurrency scaling for them."],
 a:[0],
 x:["Redshift data sharing gives consumers live access to the producer's data across accounts without copying it, and the consumer's queries run on its own Serverless compute.",
    "Unloading every 15 minutes is a new pipeline that copies data, and the results always lag the loads.",
    "Restoring snapshots repeatedly copies the whole warehouse, takes time, and the restored data is always stale.",
    "The finance team would query the producer cluster directly instead of using its own workgroup, so its workload is not separated from the producer's."],
 ref:["d10e6","d10c3"], doc:"redshift"},
{id:"m2-028", day:"mock", dom:1, tags:["Route 53","KMS & encryption"],
 q:"A bank hosts the public DNS zone for its online banking domain in an Amazon Route 53 public hosted zone, and the domain is registered with a third-party registrar. After a phishing campaign, the security team requires that DNS resolvers on the internet be able to verify cryptographically that answers for the domain come from the bank's zone and were not altered. The goal is to protect customers from DNS spoofing and cache poisoning. Which combination of actions meets these requirements? (Choose two.)",
 o:["Turn on DNSSEC validation in Route 53 Resolver for the VPCs that host the online banking application",
    "Enable DNSSEC signing on the hosted zone with a key-signing key backed by an asymmetric KMS key in us-east-1",
    "Enable Route 53 query logging for the hosted zone and alarm on queries that come from unknown resolvers",
    "Associate a Route 53 Resolver DNS Firewall rule group that blocks lookalike domains with the bank's VPCs",
    "Add the key-signing key's DS record to the parent zone through the registrar to establish a chain of trust"],
 a:[1,4],
 x:["Resolver DNSSEC validation checks the signatures on answers for queries made from the VPCs; it does not sign the bank's zone for customers on the internet.",
    "With DNSSEC signing enabled, Route 53 signs the zone's records; the key-signing key must use a customer managed asymmetric KMS key (ECC_NIST_P256) in us-east-1, and Route 53 manages the zone-signing key.",
    "Query logs show who asked for which names, but they do not let resolvers verify that the answers are authentic.",
    "DNS Firewall filters outbound queries from the bank's own VPCs; it does nothing for customers' resolvers on the internet.",
    "Validating resolvers trust the signatures only when the parent zone publishes a DS record for the key-signing key, which the bank adds through its registrar."],
 ref:["d8e3","d2w1"], doc:"route53"},
{id:"m2-029", day:"mock", dom:2, tags:["Aurora","High availability design"],
 q:"An online marketplace runs an Amazon Aurora MySQL DB cluster that has only a writer instance, and all reads also go to the writer. During an Availability Zone outage last quarter, the database was unavailable for more than 10 minutes because the cluster had no instance in another AZ to fail over to. The company needs automatic failover that completes in about a minute or less, and it wants to move read traffic off the writer. Which solution meets these requirements?",
 o:["Add Aurora Replicas in two other AZs and send read traffic to the cluster's reader endpoint.",
    "Enable Aurora Backtrack with a 24-hour window so that the cluster can be rewound after a failure.",
    "Add a secondary Region to the cluster with Aurora Global Database and send reads to the secondary.",
    "Convert the writer to an Aurora serverless instance so that capacity scales automatically during an outage."],
 a:[0],
 x:["With Aurora Replicas in other AZs, Aurora promotes a replica when the writer or its AZ fails, typically in less than a minute and often in about 30 seconds, and the reader endpoint spreads read connections across the replicas.",
    "Backtrack rewinds the database to an earlier point in time to undo logical errors; it does nothing for availability during an AZ failure.",
    "A Global Database secondary Region is for Regional disaster recovery; the primary cluster would still have no in-Region replica to fail over to, so an AZ failure would again leave the cluster without a writer until a new instance is created.",
    "Aurora serverless (formerly Aurora Serverless v2) changes how capacity scales, but a cluster with a single instance still has no replica to fail over to."],
 ref:["d9e3","d3w2"], doc:"aurora"},
{id:"m2-030", day:"mock", dom:1, tags:["Threat detection","Organizations & SCPs"],
 q:"A company has 40 accounts in AWS Organizations and runs workloads in three Regions. The security team wants a single place to view and triage findings from GuardDuty, Amazon Inspector, and Amazon Macie for all accounts and Regions, together with automated checks against security best practices. Accounts that join the organization must be enrolled automatically. Which solution requires the LEAST operational effort?",
 o:["Create an organization trail in CloudTrail, deliver it to a central bucket, and query the findings with Athena.",
    "Use an AWS Config aggregator in the security account to collect data from all accounts and Regions.",
    "Create EventBridge rules in every account and Region that forward findings to a central SNS topic.",
    "Make a security account the Security Hub CSPM delegated administrator, auto-enable members, and aggregate Regions."],
 a:[3],
 x:["CloudTrail records API activity, not security findings, and building Athena queries for each service's data adds ongoing work.",
    "A Config aggregator collects configuration and compliance data only; it does not ingest GuardDuty, Inspector, or Macie findings.",
    "Hundreds of rules across accounts and Regions are hard to maintain, new accounts need manual setup, and SNS provides no triage view or best-practice checks.",
    "AWS Security Hub CSPM (formerly AWS Security Hub) integrates with Organizations so a delegated administrator auto-enables new accounts; it ingests GuardDuty, Inspector, and Macie findings, runs best-practice checks such as AWS Foundational Security Best Practices, and cross-Region aggregation brings every Region into one home Region."],
 ref:["d8e3","d4c3"], doc:"securityhub"},
{id:"m2-031", day:"mock", dom:4, tags:["DynamoDB"],
 q:"A retailer's product catalog service reads items by primary key from a DynamoDB table in provisioned capacity mode with steady traffic, and read capacity is the largest part of the table's cost. Every GetItem call currently requests a strongly consistent read, but catalog updates are infrequent and pages may show data that is a second or two old. Reads are spread evenly across millions of products, so very few items are read again within minutes. The company wants the lowest read cost with a minimal code change. Which solution meets these requirements?",
 o:["Add a DynamoDB Accelerator (DAX) cluster in front of the table and send all GetItem calls through it.",
    "Change the reads to TransactGetItems calls so that items are read in groups with fewer requests per page.",
    "Switch the GetItem calls to eventually consistent reads and lower the provisioned read capacity.",
    "Switch the table to on-demand capacity mode so that the company pays only for the reads that it performs."],
 a:[2],
 x:["DAX helps when the same items are read repeatedly; with reads spread evenly across millions of items, most requests would miss the cache, and the cluster's nodes add cost.",
    "Transactional reads consume two read capacity units per 4 KB, twice as much as strongly consistent reads, so the cost would rise.",
    "An eventually consistent read of an item up to 4 KB uses half a read capacity unit, half the cost of a strongly consistent read, and only the ConsistentRead parameter changes; slightly stale data is acceptable here.",
    "On-demand removes capacity planning, but a steady workload usually costs more on demand than well-utilized provisioned capacity, and strongly consistent reads would still be billed at the full rate."],
 ref:["d11e4","d3p2"], doc:"dynamodb"},
{id:"m2-032", day:"mock", dom:3, tags:["Load balancing"],
 q:"An ad-tech company's bidding service receives a custom binary protocol over TCP from partner exchanges. Traffic can reach millions of requests per second with sudden spikes, and latency must be as low as possible. Partners require one fixed IP address per Availability Zone to allowlist in their firewalls, and the service must see each client's source IP address. Which solution meets these requirements?",
 o:["An Application Load Balancer placed behind AWS Global Accelerator for static anycast IP addresses.",
    "A Gateway Load Balancer with the bidding instances registered as appliance targets.",
    "A Network Load Balancer with an Elastic IP address assigned to its subnet in each Availability Zone.",
    "A Classic Load Balancer with cross-zone load balancing and TCP listeners on each port."],
 a:[2],
 x:["ALB handles only HTTP, HTTPS, and gRPC, so it cannot process a custom TCP protocol, and Global Accelerator provides two anycast IP addresses rather than one per AZ.",
    "Gateway Load Balancer transparently inserts third-party virtual appliances such as firewalls using GENEVE; it is not meant to serve application traffic.",
    "NLB operates at layer 4, scales to millions of requests per second with very low latency, supports one Elastic IP address per AZ subnet, and preserves client source IP addresses for instance targets.",
    "Classic Load Balancer is the previous generation of load balancer, which AWS recommends migrating away from; one static or Elastic IP address per Availability Zone is a Network Load Balancer capability."],
 ref:["d10e5","d5c1"], doc:"elb"},
{id:"m2-033", day:"mock", dom:2, tags:["Streaming","SNS"],
 q:"A ride-sharing company publishes about 20,000 trip events per second. Three teams (pricing, fraud detection, and analytics) must each process every event independently within seconds, in order for each trip, and at their own pace. After deploying model fixes, the fraud team must be able to reprocess the previous 48 hours of events. Which solution meets these requirements?",
 o:["Publish events to an Amazon SQS standard queue that all three teams' consumers poll.",
    "Publish events to an SNS standard topic that fans out to one SQS standard queue per team.",
    "Publish events to an Amazon Data Firehose stream that delivers them to S3 for the teams.",
    "Publish events to a Kinesis data stream keyed by trip ID with retention of at least 48 hours."],
 a:[3],
 x:["Each SQS message is delivered to one consumer and then deleted, so the teams would compete for events instead of each receiving every event, and standard queues do not preserve order.",
    "Fan-out gives each team its own copy, but standard topics and queues neither preserve per-trip order nor let the fraud team replay messages it has already deleted.",
    "Firehose is a delivery service: producers put records in and it writes buffered batches to a destination such as S3, so the teams would be reading files after the fact instead of each consuming an ordered stream at its own pace.",
    "Each consumer reads the stream independently with its own position, records with the same partition key stay ordered within a shard, and extended retention lets the fraud team re-read the last 48 hours."],
 ref:["d9e2","d6c3"], doc:"kinesis"},
{id:"m2-034", day:"mock", dom:1, tags:["IAM policies","Root user & MFA"],
 q:"A company still has IAM users in a legacy account. Engineers use long-term access keys with the AWS CLI for routine tasks. Security requires that <code>ec2:StopInstances</code> and <code>ec2:TerminateInstances</code> succeed only when the engineer has authenticated with MFA, while all other permitted actions keep working with plain access keys. Which policy change meets these requirements?",
 o:["Attach a policy that denies the two actions with a <code>Bool</code> condition on <code>aws:MultiFactorAuthPresent</code> set to false.",
    "Attach a policy that denies the two actions with a <code>BoolIfExists</code> condition on <code>aws:MultiFactorAuthPresent</code> set to false.",
    "Require a virtual MFA device for every IAM user's console sign-in and leave the existing policies unchanged.",
    "Update the account password policy to require MFA and rotate every access key at least every 90 days."],
 a:[1],
 x:["Requests signed with long-term access keys do not include the <code>aws:MultiFactorAuthPresent</code> key at all, so a <code>Bool</code> condition does not match and the deny never applies to them.",
    "<code>BoolIfExists</code> also matches when the key is missing, so the deny applies both to long-term keys and to sessions without MFA. Engineers call <code>aws sts get-session-token</code> with their MFA code to get credentials that pass.",
    "Console MFA protects console sign-in only; CLI requests made with access keys never prompt for MFA, so the actions would still succeed.",
    "An IAM password policy cannot require MFA, and rotating keys does not make any API call depend on MFA."],
 ref:["d8e2","d4b1"], doc:"iam"},
{id:"m2-035", day:"mock", dom:4, tags:["VPC peering & Transit Gateway","Data transfer costs"],
 q:"A company has two VPCs in the same Region with non-overlapping CIDR blocks. A database in one VPC replicates about 200 TB per month to analytics servers in the other VPC. No other VPCs, accounts, or on-premises networks will need to connect to them for the foreseeable future. The company wants the MOST cost-effective connectivity between the two VPCs. Which solution meets these requirements?",
 o:["Attach both VPCs to a transit gateway and add routes to the transit gateway in each VPC.",
    "Expose the analytics servers through an NLB endpoint service and create an interface endpoint in the database VPC.",
    "Create a VPC peering connection and add routes for each other's CIDR block in both VPCs.",
    "Run a software VPN appliance on EC2 in each VPC and tunnel the traffic between them."],
 a:[2],
 x:["Transit Gateway charges per attachment hour plus a per-GB data processing fee; with only two VPCs, that fee on 200 TB a month buys nothing that peering does not provide.",
    "PrivateLink charges per endpoint hour and per GB processed and exposes specific services in one direction, which suits service sharing rather than bulk replication between VPCs.",
    "Peering has no hourly or data processing charge; you pay only standard data transfer, which is free within the same AZ. For two VPCs with no growth plans, its non-transitive routing does not matter.",
    "VPN appliances add instance costs and management overhead, their throughput is bounded by the instances, and the data still incurs transfer charges."],
 ref:["d11e5","d2c2"], doc:"vpc"},
{id:"m2-036", day:"mock", dom:1, tags:["CloudFront","S3 security"],
 q:"An e-learning company stores course videos as HLS streams, each made of hundreds of segment files, in a private S3 bucket and delivers them through Amazon CloudFront. Only logged-in subscribers may watch. The video player requests segment URLs exactly as listed in the playlists, so the company cannot change those URLs. The bucket must not be reachable except through CloudFront. Which combination of steps meets these requirements? (Choose two.)",
 o:["Generate CloudFront signed URLs for every segment file listed in each playlist.",
    "Configure origin access control on the S3 origin and allow only the distribution in the bucket policy.",
    "Generate S3 presigned URLs for the segments when a subscriber starts playback.",
    "Enable S3 static website hosting and restrict access with a bucket policy on the Referer header.",
    "Issue CloudFront signed cookies scoped to the course path after a subscriber logs in."],
 a:[1,4],
 x:["Signed URLs require rewriting every segment URL, which the company cannot do, and signing hundreds of URLs per video is cumbersome compared with cookies.",
    "OAC lets CloudFront sign its requests to S3, and a bucket policy that allows only the CloudFront service principal for this distribution (through <code>aws:SourceArn</code>) blocks direct access to the bucket.",
    "Presigned URLs let viewers fetch objects directly from S3, bypassing CloudFront, and would still require changing every segment URL.",
    "Website endpoints must be publicly readable and cannot use OAC, and the Referer header is trivially spoofed.",
    "Signed cookies authorize access to many files under a path without changing their URLs, which is the intended choice for HLS segments and restricted areas of a site."],
 ref:["d8e3","d10b1"], doc:"cloudfront"},
{id:"m2-037", day:"mock", dom:3, tags:["Analytics","EC2 purchase options"],
 q:"A financial analytics firm runs nightly Apache Spark jobs on a self-managed Hadoop cluster on premises. The jobs depend on custom Spark configuration, third-party JARs, and a specific Spark version, and they process about 30 TB per night. The firm is moving to AWS and wants minimal code changes, data stored in S3, compute paid for only while the jobs run, and Spot Instances for most of the processing capacity. Which solution meets these requirements?",
 o:["Rewrite the jobs as AWS Glue ETL jobs that a scheduled Glue trigger starts each night.",
    "Translate the jobs into Athena SQL queries that EventBridge Scheduler runs each night.",
    "Run Spark on EC2 On-Demand instances that stay up all day, managed with custom scripts.",
    "Run a transient Amazon EMR cluster each night with Spot task nodes and the data in S3."],
 a:[3],
 x:["Glue runs serverless Spark on capacity that AWS manages: the Glue version, not the firm, determines the Spark version, the jobs need rework, and there are no cluster instances for the firm to buy as Spot Instances.",
    "Rewriting Spark logic as SQL is a major code change, and complex jobs with custom libraries may not translate at all.",
    "Instances that run all day pay for idle compute and add self-management overhead, the opposite of paying only while jobs run.",
    "EMR runs open-source Spark with your chosen release, configuration, and JARs; a transient cluster with Spot task nodes uses S3 for storage and terminates when the steps finish, so you pay only during the run."],
 ref:["d10e6","d10c3"], doc:"emr"},
{id:"m2-038", day:"mock", dom:2, tags:["S3 features","S3 storage classes & lifecycle"],
 q:"A design agency stores project files in an S3 bucket. A faulty script recently deleted thousands of objects and overwrote others with empty files, and none could be recovered. The agency must be able to restore any deleted or overwritten object for 30 days after the change. Files are edited many times a day, so storage costs must not grow without limit. Which combination of steps meets these requirements? (Choose two.)",
 o:["Enable S3 Versioning on the bucket.",
    "Enable MFA Delete on the bucket.",
    "Add a lifecycle rule that permanently deletes noncurrent versions 30 days after they become noncurrent.",
    "Configure S3 Replication to a bucket in another Region.",
    "Add a lifecycle rule that transitions current objects to S3 Glacier Flexible Retrieval after 30 days."],
 a:[0,2],
 x:["With versioning, a delete adds a delete marker and an overwrite creates a new version, so earlier versions remain available to restore.",
    "MFA Delete only requires MFA to permanently delete versions or change the versioning state, and S3 does not support lifecycle rules on MFA Delete-enabled buckets, which this agency needs to control cost.",
    "Noncurrent version expiration keeps each previous version for 30 days so that it can be restored, then deletes it automatically, preventing storage from growing indefinitely.",
    "Replication requires versioning on both buckets anyway and doubles storage cost; the ability to recover comes from versioning itself, and replicating every edit adds cost rather than limiting it.",
    "Archiving current files that are edited daily makes them slow to open and adds retrieval charges, and it provides no way to recover deleted or overwritten objects."],
 ref:["d9e3","d3b1"], doc:"s3"},
{id:"m2-039", day:"mock", dom:1, tags:["Secrets Manager & Parameter Store","Containers"],
 q:"A retail company runs 30 microservices on Amazon ECS. Each service needs about 20 configuration values, including partner API tokens that are issued manually and are never rotated automatically. The values must be encrypted at rest with a customer managed KMS key, keep a version history, and be injected into containers as environment variables at startup. The company wants the MOST cost-effective solution. Which solution meets these requirements?",
 o:["Store each value as a secret in Secrets Manager with rotation disabled and reference the secrets in the task definitions.",
    "Store each value as a SecureString parameter in Parameter Store and reference the parameters in the task definitions.",
    "Place the values as plaintext environment variables in each task definition and encrypt the task definitions with KMS.",
    "Store the values in a DynamoDB table encrypted with the key and read them with SDK calls when each container starts."],
 a:[1],
 x:["This works, but Secrets Manager charges per secret per month, which adds up across about 600 values, and its main advantage, managed rotation, is not needed here.",
    "SecureString parameters are encrypted with the KMS key you choose and keep a version history, standard-tier parameters have no storage charge, and ECS injects them as environment variables through the <code>secrets</code> section of the task definition.",
    "Environment variables written into a task definition are readable by every user and role that is allowed to describe the task definition, which is why AWS recommends Secrets Manager or Parameter Store for sensitive values.",
    "This needs custom code in every service to fetch values at startup, and ECS does not inject them, adding effort with no benefit over Parameter Store."],
 ref:["d8e3","d4b5"], doc:"parameter-store"},
{id:"m2-040", day:"mock", dom:4, tags:["EBS & instance store"],
 q:"A media company takes a monthly EBS snapshot of each of its archive volumes and must keep every monthly snapshot for 7 years for compliance. The volumes' contents are largely replaced each month, so every snapshot holds mostly new data. The snapshots are almost never restored, and when an audit needs one, a restore time of up to 3 days is acceptable. Snapshot storage has become a significant cost. Which solution is the MOST cost-effective?",
 o:["Copy each monthly snapshot to a second Region and delete the original snapshot in the source Region.",
    "Keep the snapshots in the standard tier and enable fast snapshot restore on them for faster audits.",
    "Register each snapshot as an AMI and deregister the AMIs again after each audit has been completed.",
    "Move each monthly snapshot to the EBS Snapshots Archive tier after it is created and restore it when needed."],
 a:[3],
 x:["A cross-Region copy is again a standard-tier snapshot, with data transfer on top, so the bill does not go down.",
    "Fast snapshot restore adds an hourly charge for each snapshot in each AZ and speeds up restores that the company does not need quickly.",
    "AMIs are backed by the same snapshots at the same price, and deregistering an AMI does not reduce storage while the snapshots must be kept.",
    "The archive tier stores snapshots at a much lower price than the standard tier for snapshots kept 90 days or more and rarely accessed; restores take up to 72 hours, within the 3-day window."],
 ref:["d11e2","d3c1"], doc:"ebs"},
{id:"m2-041", day:"mock", dom:2, tags:["Route 53"],
 q:"A SaaS company runs identical application stacks behind Application Load Balancers in us-east-1, eu-west-1, and ap-southeast-2. Users must be sent to the Region that gives them the lowest network latency. If the application in a Region stops responding, its users must automatically be routed to the next-best Region without anyone changing DNS records. Which Amazon Route 53 configuration meets these requirements?",
 o:["Latency-based alias records for the three ALBs with Evaluate Target Health enabled.",
    "Geolocation records for each continent with a default record and health checks on each ALB.",
    "Failover records with us-east-1 as the primary and the other two Regions as secondary records.",
    "Multivalue answer records that return all three ALB addresses with a health check on each."],
 a:[0],
 x:["Latency routing answers with the Region that has the lowest measured latency for the user, and Evaluate Target Health removes a Region whose ALB has no healthy targets, so its users fall back to the next-lowest-latency Region automatically.",
    "Geolocation routes by the user's location, not measured latency, so users near a boundary or on distant networks may not get the fastest Region.",
    "Failover routing is active-passive: everyone is sent to the primary while it is healthy and to a secondary only when it is not, so latency is never considered.",
    "Multivalue answers return several healthy addresses in random order for the client to choose from, without considering latency."],
 ref:["d9e3","d9c3"], doc:"route53"},
{id:"m2-042", day:"mock", dom:3, tags:["Lambda"],
 q:"An image-processing Lambda function is configured with 512 MB of memory. CloudWatch shows it uses about 180 MB at most, but invocations average 9 seconds, and profiling shows the code is CPU-bound and multithreaded. The team must cut duration substantially without code changes and wants the cost per invocation to rise as little as possible. What should the team do?",
 o:["Enable provisioned concurrency for the function to keep execution environments initialized.",
    "Increase the memory setting and benchmark several sizes to find the best balance of duration and cost.",
    "Reduce the memory setting to 256 MB because the function never uses more than 180 MB.",
    "Increase the function's ephemeral storage to 10 GB to give the image library more working space."],
 a:[1],
 x:["Provisioned concurrency removes cold-start initialization time, but this function is slow during execution, which stays the same, and it adds a constant charge.",
    "Lambda allocates CPU in proportion to memory (one full vCPU at 1,769 MB, up to 6 vCPUs at 10,240 MB), so more memory speeds up CPU-bound, multithreaded code; because billing is memory times duration, a shorter run often keeps the cost similar.",
    "Less memory also means less CPU, which makes a CPU-bound function even slower.",
    "Ephemeral storage adds /tmp disk space; it does not add CPU and would not speed up computation."],
 ref:["d10e3","d1w3"], doc:"lambda"},
{id:"m2-043", day:"mock", dom:1, tags:["Instance access","VPC & subnets"],
 q:"A company runs network appliances from a vendor AMI on EC2 instances in private subnets with no public IP addresses. The vendor's license forbids installing additional software, so the Systems Manager Agent cannot be added. Engineers must connect with standard SSH clients, the company wants to remove its internet-facing bastion host, and every connection must be authorized with IAM and recorded in CloudTrail. Which solution meets these requirements?",
 o:["Assign Elastic IP addresses to the instances and allow SSH only from the engineers' office IP range.",
    "Install the SSM Agent with a user data script at launch and connect through Session Manager port forwarding.",
    "Create an EC2 Instance Connect Endpoint in the VPC and allow SSH to the instances only from the endpoint.",
    "Replace the bastion host with an AWS Client VPN endpoint and let the engineers SSH to the instances over it."],
 a:[2],
 x:["Elastic IP addresses give the appliances public addresses, adding internet exposure, and access depends on source IP rather than IAM, with no CloudTrail record of each connection.",
    "The license forbids installing additional software, so adding the SSM Agent is not allowed.",
    "An EC2 Instance Connect Endpoint opens private SSH tunnels to instances without public IPs, agents, or a bastion; IAM policies control who may open a tunnel, and each attempt is logged in CloudTrail.",
    "Client VPN authenticates users with certificates, Active Directory, or SAML rather than per-instance IAM permissions, and it adds a VPN endpoint to operate."],
 ref:["d8e3","d2b3"], doc:"ec2"},
{id:"m2-044", day:"mock", dom:2, tags:["SQS","CloudWatch"],
 q:"An order pipeline uses an Amazon SQS standard queue consumed by a Lambda function. Occasionally a malformed message from a legacy system makes the function throw an exception every time. Such messages are retried for 4 days until the retention period expires, which wastes Lambda invocations and hides the problem. The team wants these messages set aside after a few failed attempts, kept for investigation, and operators alerted. Which solution meets these requirements?",
 o:["Configure an on-failure destination on the Lambda function that sends failed events to an SNS topic.",
    "Reduce the source queue's message retention period to 1 hour so that failing messages expire quickly.",
    "Increase the function timeout to 15 minutes and raise the event source mapping's batch size.",
    "Attach a dead-letter queue with a maxReceiveCount of 3 and alarm on the dead-letter queue's message count."],
 a:[3],
 x:["On-failure destinations apply to asynchronous invocations and to stream and Kafka event sources; for an SQS event source, failed messages are handled by a dead-letter queue on the queue instead.",
    "Shorter retention also deletes valid messages that are temporarily delayed, and it discards the malformed ones instead of keeping them for investigation.",
    "A malformed message fails deterministically, so more time or larger batches only make each failure more expensive.",
    "After three failed receives, SQS moves the message to the dead-letter queue, where it can be inspected and later redriven; give the DLQ a longer retention than the source queue, and a CloudWatch alarm on ApproximateNumberOfMessagesVisible alerts operators."],
 ref:["d9e2","d9b1","d9c1"], doc:"sqs"},
{id:"m2-045", day:"mock", dom:4, tags:["DynamoDB","Analytics"],
 q:"A subscription company runs its production workload on an Amazon DynamoDB table in provisioned capacity mode. Every night, analysts run full table scans to build reports, which forces the company to provision far more read capacity than the application needs and sometimes throttles production reads. The reports can use data that is up to a day old. Which solution reduces cost the MOST without affecting production traffic?",
 o:["Turn on point-in-time recovery, export the table to S3 each night, and query the export with Athena.",
    "Add a global secondary index that projects all attributes and run the nightly scans against the index.",
    "Switch the table to on-demand capacity mode so that the nightly scans no longer need provisioned capacity.",
    "Put a DynamoDB Accelerator (DAX) cluster in front of the table and run the analysts' scans through DAX."],
 a:[0],
 x:["Export to S3 reads from point-in-time recovery data and consumes no table read capacity, so production is unaffected, and Athena queries the exported files at a low per-query cost.",
    "An index with all attributes duplicates the table's storage and write costs, and scanning it still consumes read capacity on the index.",
    "On-demand mode still charges for every read request in the scans, so large nightly scans remain expensive.",
    "DAX helps repeated reads of the same items; a full scan reads every item once, so it gains little and adds a cluster to pay for."],
 ref:["d11e4","d10c3"], doc:"dynamodb"},
{id:"m2-046", day:"mock", dom:1, tags:["AWS Config","Governance"],
 q:"A company's compliance team has defined 35 AWS Config managed rules with company-specific parameters in a single YAML template. The rules must run in all 120 accounts of the company's organization in AWS Organizations, including accounts created later, and the compliance team wants one compliance view per account for the whole set. AWS Config is already recording in every account, and the security account is the delegated administrator for AWS Config. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Create an organization-wide AWS Config aggregator in the security account and add the rules to the aggregator.",
    "Have each account owner deploy the template as a conformance pack in their own account and in every new account.",
    "Deploy the template as an organization conformance pack from the delegated administrator account for AWS Config.",
    "Enable the AWS Trusted Advisor organizational view and turn on the checks that match the compliance team's rules."],
 a:[2],
 x:["An aggregator only collects configuration and compliance data from the accounts; rules cannot be added to it, so nothing would be evaluated.",
    "Per-account deployment depends on every owner, including the owners of new accounts, to act, which is the manual effort the company wants to avoid.",
    "An organization conformance pack deploys the whole set of rules to every member account, including new ones, and reports compliance for the pack as a unit in each account.",
    "The organizational view aggregates the results of Trusted Advisor's own checks across accounts, which are not the company's parameterized Config rules."],
 ref:["d8e4","d6c1","d6w2"], doc:"config"},
{id:"m2-047", day:"mock", dom:3, tags:["Purpose-built databases","DynamoDB"],
 q:"An online marketplace stores 50 million product listings in DynamoDB. Customers need a search box that supports full-text search, typo tolerance, relevance ranking, and faceted filtering by price and brand, returning results in under 200 ms. Listings change often, and search results should reflect changes within seconds. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Add global secondary indexes for brand and price and run Scan operations with contains() filter expressions.",
    "Replicate listings to Amazon OpenSearch Service with the DynamoDB zero-ETL integration and query that index.",
    "Export the table to S3 every hour and run Athena queries that use LIKE patterns on the listing text.",
    "Use DynamoDB Streams and a Lambda function to maintain an inverted index of words in a second table."],
 a:[1],
 x:["Scans with filters read the entire table, are slow and costly at this size, and offer no relevance ranking or fuzzy matching.",
    "OpenSearch Service provides full-text search with fuzzy matching, relevance scoring, and aggregations for facets, and the zero-ETL integration (built on OpenSearch Ingestion) keeps the index in sync with the table in near real time without custom pipelines.",
    "Hourly exports are far from near real time, and Athena queries take seconds and lack relevance ranking.",
    "Building and maintaining a custom inverted index is significant engineering effort and still lacks typo tolerance and ranking."],
 ref:["d10e4","d10c3"], doc:"opensearch"},
{id:"m2-048", day:"mock", dom:2, tags:["Internet & NAT gateways","High availability design"],
 q:"A company's VPC spans three Availability Zones. Application servers in private subnets in all three AZs reach third-party APIs through a single zonal NAT gateway in AZ A, and every private route table sends <code>0.0.0.0/0</code> to it. When AZ A had an outage, servers in the other two AZs lost outbound internet access. The company wants outbound access to continue in the remaining AZs if any one AZ fails and wants to avoid sending this traffic across AZs. Which combination of steps meets these requirements? (Choose two.)",
 o:["Create a NAT gateway in a public subnet in each of the three Availability Zones.",
    "Replace the NAT gateway route in each private route table with a route to the internet gateway.",
    "Associate a secondary Elastic IP address with the existing NAT gateway in AZ A.",
    "Create gateway VPC endpoints for the domains of the third-party APIs.",
    "Use a separate route table per AZ that sends <code>0.0.0.0/0</code> to the NAT gateway in the same AZ."],
 a:[0,4],
 x:["A zonal NAT gateway is redundant only within its own AZ, so placing one in each AZ removes the dependency on AZ A. (A regional NAT gateway is an alternative that expands across AZs automatically.)",
    "Routing private subnets to the internet gateway turns them into public subnets and works only if the servers have public IP addresses, which defeats the private design.",
    "Extra IP addresses add connection capacity, but the gateway still lives in AZ A and fails with it.",
    "Gateway endpoints exist only for Amazon S3 and DynamoDB; they cannot reach third-party APIs on the internet.",
    "Pointing each AZ's private subnets at the NAT gateway in the same AZ keeps traffic local, avoiding cross-AZ data charges, and confines an outage to the failed AZ."],
 ref:["d9e3","d2b1"], doc:"vpc"},
{id:"m2-049", day:"mock", dom:1, tags:["S3 security","IAM roles & cross-account"],
 q:"A healthcare analytics company receives daily files from 12 partner AWS accounts. Partner applications write objects directly into one of the company's S3 buckets, created several years ago, through a bucket policy that grants <code>s3:PutObject</code> to the partner accounts. The company's data engineers get AccessDenied errors when reading some uploaded objects. The security team wants access to every object controlled only by the company's own policies, without depending on partners to set ACLs. Which solution meets these requirements?",
 o:["Require the <code>bucket-owner-full-control</code> canned ACL on every upload with a bucket policy condition.",
    "Enable S3 Block Public Access on the bucket and on the company's account.",
    "Set S3 Object Ownership on the bucket to bucket owner enforced.",
    "Turn on default SSE-KMS encryption with a key that the data engineers are allowed to use."],
 a:[2],
 x:["This older workaround still depends on partners sending the ACL with every request and keeps ACLs in play, which the security team wants to avoid.",
    "Block Public Access prevents public exposure; it does not change who owns objects written by other accounts.",
    "Bucket owner enforced disables ACLs and makes the bucket owner the owner of every object, so access is governed only by the company's bucket and IAM policies, whoever uploads the object. New buckets use this setting by default.",
    "Encryption settings do not change object ownership, so the engineers would still lack access to objects owned by partner accounts."],
 ref:["d8e4","d4c1"], doc:"s3"},
{id:"m2-050", day:"mock", dom:3, tags:["Streaming","AI/ML services"],
 q:"A home security company sells cameras that stream live video to the cloud. Hundreds of thousands of cameras must send video securely to AWS, customers must be able to watch live and recorded video in the mobile app, and footage must be kept for 30 days with time-indexed playback. The company also wants still images extracted from each live stream and delivered to Amazon S3, where a person-detection job analyzes them. It wants a fully managed ingestion service that scales without servers to manage. Which solution meets these requirements?",
 o:["Amazon Kinesis Data Streams with one shard per camera and a consumer that writes video frames to S3.",
    "Amazon Data Firehose streams that buffer the camera video and deliver it to an S3 bucket every minute.",
    "AWS Elemental MediaConvert jobs that transcode each camera's video into adaptive bitrate files in S3.",
    "Amazon Kinesis Video Streams with 30-day retention, HLS playback, and automatic image generation to S3."],
 a:[3],
 x:["Data Streams is built for data records, not media, so the company would have to build video fragmenting, storage, time indexing, and playback itself.",
    "Firehose buffers records and delivers batches to destinations such as S3; live viewing, time-indexed playback, and image extraction are Kinesis Video Streams features.",
    "MediaConvert is a file-based video processing service for offline content, so it neither ingests live camera streams nor plays them back.",
    "Kinesis Video Streams ingests media from very large numbers of devices, stores it durably with time indexing for the retention period you set, plays live and archived video through HLS, and can extract images from a stream as it is ingested and deliver them to S3, where Amazon Rekognition image analysis can detect people. (Rekognition's own stream processors for streaming video are closed to new customers.)"],
 ref:["d10e6","d6c3"], doc:"kvs"},
{id:"m2-051", day:"mock", dom:4, tags:["Containers","EC2 purchase options"],
 q:"A company runs 120 Amazon ECS tasks on AWS Fargate around the clock for an API backend. Each task uses 2 vCPU and 4 GB of memory, the task count has barely changed for a year, and it is expected to stay the same for at least three more years. The platform team already operates EC2 Auto Scaling groups for other workloads and is comfortable patching instances. The API must not lose capacity to interruptions, and management wants the LOWEST compute cost for this workload. Which solution meets these requirements?",
 o:["Keep the tasks on Fargate and cover their steady usage with a 3-year Compute Savings Plan.",
    "Move all tasks to Fargate Spot and let the ECS service replace any tasks that are interrupted.",
    "Run the tasks on ECS with right-sized EC2 instances covered by a 3-year EC2 Instance Savings Plan.",
    "Rewrite the API as Lambda functions behind API Gateway to pay only per request."],
 a:[2],
 x:["This lowers the bill, but Fargate's per-vCPU price includes a premium for managing the hosts, and Compute Savings Plans discount Fargate less than EC2 Instance Savings Plans discount EC2, so it is not the lowest cost.",
    "Fargate Spot tasks can be interrupted with a two-minute warning when AWS needs the capacity back, which this API cannot tolerate.",
    "For a steady, predictable workload and a team willing to manage instances, well-packed EC2 instances cost less per vCPU than Fargate, and an EC2 Instance Savings Plan gives the deepest Savings Plan discount for a 3-year commitment.",
    "A constantly busy API usually costs more on Lambda than on always-on compute, and rewriting it is a large effort."],
 ref:["d11e3","d11c2"], doc:"ecs"},
{id:"m2-052", day:"mock", dom:2, tags:["SNS","SQS"],
 q:"A stock trading platform publishes order-status events that three downstream services must each receive: billing, notifications, and audit. Each service must process the events for a given order in exactly the order they were published, and duplicate publishes during producer retries must not cause duplicate processing. The services must be decoupled so that any one of them can be down for maintenance without losing events. Which solution meets these requirements?",
 o:["Publish the events to an SNS standard topic with a separate SQS standard queue subscribed for each service.",
    "Publish the events to one SQS FIFO queue that all three services poll and delete messages from when done.",
    "Publish the events to an EventBridge custom event bus with a rule that targets a Lambda function per service.",
    "Publish to an SNS FIFO topic with the order ID as the message group ID and an SQS FIFO queue for each service."],
 a:[3],
 x:["Standard topics and queues provide best-effort ordering and at-least-once delivery, so events can arrive out of order or more than once.",
    "With one queue, each message is consumed by only one of the services, so the other two would never see it.",
    "An event sent to an EventBridge bus carries no message group ID or deduplication ID, so the bus has nothing to order events per order or drop a retried publish with; those guarantees come from FIFO topics and queues.",
    "An SNS FIFO topic delivers each message to every subscribed SQS FIFO queue in order within each message group and deduplicates retried publishes, and each queue buffers events while its service is down."],
 ref:["d9e2","d9b2","d9c1"], doc:"sns"},
{id:"m2-053", day:"mock", dom:1, tags:["Root user & MFA","Organizations & SCPs"],
 q:"A company has 300 member accounts in AWS Organizations. Every member account still has a root user password and MFA device that the security team must store, protect, and audit, which is a growing burden and risk. The company wants member accounts to have no long-term root credentials at all, but administrators must still be able to perform rare root-only tasks, such as deleting an S3 bucket policy that accidentally denies all principals. Which solution meets these requirements with the least operational overhead?",
 o:["Attach an SCP to all OUs that denies every action by the root user, and keep the root passwords in a vault.",
    "Enable centralized root access management in IAM, delete member root credentials, and use root sessions.",
    "Store each root password in AWS Secrets Manager and require an approval before anyone retrieves one.",
    "Create an IAM user with the AdministratorAccess policy in each account for tasks that need the root user."],
 a:[1],
 x:["The SCP blocks the root user, but the credentials still exist and must be managed, and it also prevents the root-only tasks that administrators still need.",
    "Centralized root access management lets the management account or a delegated administrator remove root credentials from member accounts and start short-lived privileged root sessions for tasks such as deleting a misconfigured bucket policy.",
    "The long-term root credentials would still exist in every account and would still have to be protected and audited.",
    "Root-only tasks cannot be performed by an IAM user, even one with AdministratorAccess, and new IAM users add more long-term credentials."],
 ref:["d8e2","d1b1","d4c2"], doc:"iam"},
{id:"m2-054", day:"mock", dom:3, tags:["Purpose-built databases"],
 q:"A smart-building company is moving two data stores to AWS. The first is an on-premises Apache Cassandra cluster that holds billions of sensor readings; dozens of services read and write it through CQL drivers, and the company wants a serverless replacement without rewriting that code. The second must model relationships among tenants, rooms, devices, and access badges and answer multi-hop questions, such as which badges entered rooms that contain a device that reported a fault, in milliseconds. Each store must be a fully managed, purpose-built database. Which services should the company choose? (Choose two.)",
 o:["Amazon DynamoDB for the sensor readings",
    "Amazon DocumentDB for the relationship data",
    "Amazon Keyspaces (for Apache Cassandra) for the sensor readings",
    "Amazon RDS for PostgreSQL with recursive queries for the relationship data",
    "Amazon Neptune for the relationship data"],
 a:[2,4],
 x:["DynamoDB is serverless and scales well, but it has its own API, so every service that uses CQL would have to be rewritten.",
    "DocumentDB stores JSON documents; following relationships across several hops requires many lookups and is inefficient.",
    "Keyspaces is a serverless, Cassandra-compatible database, so existing CQL drivers and application code keep working with little or no change, with no servers to provision, patch, or manage.",
    "A relational database is not purpose-built for graph traversal; recursive joins across several hops become slow as the number of relationships grows.",
    "Neptune is a managed graph database designed to traverse highly connected data across many hops with millisecond latency using Gremlin, openCypher, or SPARQL."],
 ref:["d10e4","d3w2"], doc:"keyspaces"},
{id:"m2-055", day:"mock", dom:2, tags:["EventBridge"],
 q:"An e-commerce company routes order events through an Amazon EventBridge custom event bus to several consumers through rules. Last month a bug in the fulfillment consumer silently discarded events for 6 hours, and rebuilding them from logs took days. For future incidents, the company wants to resend every event from a chosen time window to only the affected consumer after a fix is deployed, with minimal custom code. Which solution meets these requirements?",
 o:["Add a dead-letter queue to the fulfillment rule's target and redrive the queue after the fix is deployed.",
    "Create an archive on the event bus and start a replay of the time window that targets only the fulfillment rule.",
    "Add a Lambda target that writes every event to DynamoDB and a script that republishes events by timestamp.",
    "Raise the target's retry policy to the maximum event age of 24 hours so that EventBridge redelivers events."],
 a:[1],
 x:["A dead-letter queue captures only events that EventBridge failed to deliver; here delivery succeeded and the consumer discarded the events, so the queue would be empty.",
    "An EventBridge archive stores the bus's events, and a replay resends events from a chosen time range to the bus, optionally only to specific rules, so just the fulfillment consumer reprocesses them.",
    "This builds a custom event store and republishing tool, which is the custom code the company wants to avoid.",
    "Retries happen only when delivery to the target fails; the consumer accepted the events and then discarded them, so EventBridge would not redeliver anything."],
 ref:["d9e2","d9b3"], doc:"eventbridge"},
{id:"m2-056", day:"mock", dom:1, tags:["VPC & subnets","Threat detection"],
 q:"A security engineer is investigating suspected data exfiltration from EC2 instances in a VPC. GuardDuty has raised a finding, but the engineer now needs raw records of every connection for every network interface in the VPC, including source and destination IP addresses, ports, byte counts, and whether security groups or network ACLs accepted or rejected the traffic. The records must be queryable with Athena. Packet payloads are not needed, and no agents may be installed. Which solution meets these requirements?",
 o:["Enable VPC Flow Logs for the VPC, deliver them to S3 in Parquet, and query them with Athena.",
    "Configure VPC Traffic Mirroring for every instance to a fleet of packet-capture appliances.",
    "Export the VPC flow log data that GuardDuty already analyzes from the GuardDuty console.",
    "Enable Route 53 Resolver query logging for the VPC and query the DNS logs with Athena."],
 a:[0],
 x:["Flow logs record IP addresses, ports, protocol, bytes, and the ACCEPT or REJECT decision for every network interface without agents, and delivering them to S3 in Parquet makes Athena queries fast and cheap.",
    "Traffic Mirroring copies full packets, which are not needed, and requires appliances to receive and store the traffic, adding cost and operational work.",
    "GuardDuty analyzes flow log data from an independent stream for its own detections, but it does not store or expose those records to customers.",
    "Resolver query logs show DNS lookups only; connections made directly to IP addresses and accept or reject decisions would be missing."],
 ref:["d8e3","d6w2"], doc:"vpc"},
{id:"m2-057", day:"mock", dom:4, tags:["EFS"],
 q:"A legal firm stores 40 TB of case documents on Amazon EFS using the EFS Standard storage class, mounted by an application in three Availability Zones. Analysis shows that about 85% of the files have not been read in more than 60 days, but any file may be opened by an attorney at any time and must be returned directly, without a restore step. The application must keep seeing one file system. Which solution reduces storage cost the MOST with the LEAST effort?",
 o:["Enable EFS lifecycle management to move files not accessed for 30 days to EFS Infrequent Access.",
    "Move files older than 60 days to S3 Glacier Deep Archive with DataSync and leave pointer files in EFS.",
    "Copy the data to a new EFS One Zone file system and remount the application on that file system.",
    "Migrate the documents to Amazon FSx for Lustre linked to an S3 bucket for the colder files."],
 a:[0],
 x:["Lifecycle management moves cold files to the lower-cost Infrequent Access class automatically (and can tier long-untouched files further to EFS Archive), the namespace does not change, files stay directly readable with a per-GB access charge, and a policy can move them back to Standard on access.",
    "Deep Archive requires a restore that takes up to 12 hours or more, and pointer files would break the single namespace the application needs.",
    "A One Zone file system gives up multi-AZ resilience and requires a migration, and without lifecycle management it still keeps cold data at a hot-data price.",
    "FSx for Lustre is built for high-performance compute, and migrating to it is far more effort than turning on lifecycle management."],
 ref:["d11e2","d3c1"], doc:"efs"},
{id:"m2-058", day:"mock", dom:3, tags:["API Gateway","Caching"],
 q:"A weather service exposes a REST API in Amazon API Gateway backed by a Lambda function that queries an Aurora PostgreSQL database. About 90% of requests are GET /forecast with a city query string parameter, and each city's forecast changes only every 10 minutes. During peaks, p95 latency is too high and database CPU is the bottleneck. The company wants to reduce latency and database load with minimal code changes. Which solution meets these requirements?",
 o:["Enable provisioned concurrency for the Lambda function to remove cold starts during peaks.",
    "Add Aurora Replicas and change the function to send its queries to the reader endpoint.",
    "Enable stage throttling in API Gateway to cap requests at a rate the database can sustain.",
    "Enable API Gateway stage caching keyed on the city parameter with a TTL of up to 10 minutes."],
 a:[3],
 x:["Cold starts are not the bottleneck; every request would still reach the database, so its CPU stays the problem.",
    "Replicas spread the load, but every request still queries the database and the function must be changed; caching removes most queries entirely.",
    "Throttling protects the database by rejecting requests with HTTP 429, which hurts users instead of making responses faster.",
    "API Gateway caching returns stored responses for identical requests without invoking the backend; keying on the city parameter and matching the TTL to the 10-minute update cycle removes most Lambda and database work without code changes."],
 ref:["d10e5","d10b2"], doc:"apigw"},
{id:"m2-059", day:"mock", dom:2, tags:["Caching","Disaster recovery"],
 q:"A gaming company runs its platform in us-east-1 with a warm standby in eu-west-1. Live leaderboards and matchmaking state are kept in Amazon ElastiCache for Valkey. If us-east-1 becomes unavailable, the eu-west-1 stack must take over within minutes with cache data no more than seconds behind, instead of rebuilding the leaderboards from scratch. The team wants a managed solution with no custom replication code. Which solution meets these requirements?",
 o:["Create an ElastiCache Global Datastore with the us-east-1 cluster as primary and a secondary cluster in eu-west-1.",
    "Enable Multi-AZ with automatic failover on the us-east-1 cluster and add replicas in every Availability Zone.",
    "Export a backup of the cluster to S3 every hour, copy it to eu-west-1, and restore it there during a disaster.",
    "Write every cache update to both Regions from the application with a Lambda function that retries failed writes."],
 a:[0],
 x:["Global Datastore asynchronously replicates to a read-only secondary cluster in another Region with low lag, typically under a second, and the secondary can be promoted to primary within minutes during a Regional outage.",
    "Multi-AZ protects against node and AZ failures inside us-east-1 only; it keeps no copy of the data in eu-west-1.",
    "Hourly backups mean up to an hour of lost data and a slow restore, far worse than seconds.",
    "Dual writes from the application are custom replication code that is hard to keep consistent, which the team wants to avoid."],
 ref:["d9e3","d9c2"], doc:"elasticache"},
{id:"m2-060", day:"mock", dom:1, tags:["VPC & subnets","Organizations & SCPs"],
 q:"A company's networking team manages a central VPC in a networking account; the VPC has Direct Connect access and centralized internet egress. Application teams in five other accounts in the same organization need to launch EC2 instances and RDS databases from their own accounts into subnets of this VPC, so that everything shares one IP address space and routing. The networking team must keep sole control of route tables, network ACLs, and gateways. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Peer a new VPC in each application account with the central VPC and route through it.",
    "Attach a new VPC in each application account to a transit gateway shared with the central VPC.",
    "Share the central VPC's subnets with the application accounts by using AWS Resource Access Manager.",
    "Create IAM roles in the networking account that application teams assume to launch their resources."],
 a:[2],
 x:["Each application VPC would have its own IP space, and peering is not transitive, so peered VPCs cannot use the central VPC's Direct Connect or internet egress path.",
    "Transit Gateway connects separate VPCs but does not provide a single shared IP space, and it adds attachments and per-GB charges to manage.",
    "VPC sharing through AWS RAM lets participant accounts create resources that they own and pay for in the shared subnets, while the owner account alone manages the VPC, route tables, NACLs, and gateways.",
    "Resources would be created in and owned by the networking account rather than the application accounts, mixing ownership and billing."],
 ref:["d8e2","d2c2"], doc:"vpc"},
{id:"m2-061", day:"mock", dom:4, tags:["CloudWatch","S3 storage classes & lifecycle"],
 q:"A SaaS company's applications write about 5 TB of logs each month to CloudWatch Logs log groups that use the default 'Never expire' retention. Engineers query only the last 30 days with CloudWatch Logs Insights. Compliance requires keeping all logs for 7 years; older logs are almost never read, and retrieval within 48 hours is acceptable. CloudWatch Logs storage has become one of the largest costs. Which combination of steps reduces cost the MOST while meeting these requirements? (Choose two.)",
 o:["Set the retention period of the log groups to 30 days.",
    "Change all log groups to the Infrequent Access log class and keep their retention at 'Never expire'.",
    "Export the logs to S3 Standard and keep them in that storage class for the full 7 years.",
    "Stream the logs to S3 through a subscription filter and Data Firehose, with lifecycle rules to S3 Glacier Deep Archive.",
    "Create metric filters for the important log patterns and delete the raw log events after each day."],
 a:[0,3],
 x:["Retention deletes events older than 30 days from CloudWatch Logs automatically, so the company stops paying CloudWatch storage for logs that engineers never query there. Export the existing older events to S3 once before shortening retention.",
    "A log group's class cannot be changed after the group is created, and the Infrequent Access class lowers only the ingestion price; storage is billed at the same rate, so 7 years of logs in CloudWatch still cost far more than archival storage in S3.",
    "Moving logs to S3 helps, but keeping 7 years in S3 Standard costs much more than an archive class for data that is almost never read.",
    "A subscription filter streams logs to Firehose, which writes them to S3; lifecycle rules move them to Deep Archive, the cheapest class, whose standard and bulk retrievals complete within 12 and 48 hours, and expire them after 7 years.",
    "Metric filters keep only numbers derived from the logs, so deleting the raw events would violate the 7-year retention requirement."],
 ref:["d11e2","d6w2"], doc:"cloudwatch"},
{id:"m2-062", day:"mock", dom:3, tags:["Analytics"],
 q:"A marketing company receives CSV files from 30 partners in an S3 bucket each day. Partners occasionally add columns without notice. The company needs schemas discovered automatically, a catalog that Athena can query, and a nightly serverless transformation that cleans the data and writes date-partitioned Parquet files. The team writes Python but does not want to manage clusters. Which solution meets these requirements?",
 o:["Run an Amazon EMR cluster continuously with a Hive metastore and schedule PySpark scripts with cron.",
    "Use scheduled AWS Glue crawlers to update the Data Catalog and a Python AWS Glue ETL job for the nightly transformation.",
    "Invoke a Lambda function for each file to convert it to Parquet, and update Athena tables with DDL when schemas change.",
    "Send the files through Amazon Data Firehose with record format conversion to Parquet enabled."],
 a:[1],
 x:["A continuously running EMR cluster means managing and paying for servers, which the team wants to avoid.",
    "Crawlers infer schemas and detect new columns, keeping the Glue Data Catalog current for Athena, and serverless Glue ETL jobs written in PySpark (orchestrated by triggers or workflows) write partitioned Parquet with no clusters to manage.",
    "Schema changes would require manual DDL updates, and large files can exceed a standard Lambda function's 15-minute timeout or its memory.",
    "Firehose ingests streaming records; its format conversion needs a predefined Glue table schema, and it does not discover schemas or process files already stored in S3."],
 ref:["d10e6","d6w1"], doc:"glue"},
{id:"m2-063", day:"mock", dom:2, tags:["SQS","Migration & transfer"],
 q:"A logistics company is migrating an on-premises order system to AWS. Its Java applications exchange messages through an Apache ActiveMQ broker using JMS queues and topics, and several partner systems connect to the broker over AMQP and MQTT. The company wants a managed, highly available message broker in AWS and must avoid rewriting the messaging code. Which solution meets these requirements?",
 o:["Migrate to Amazon MQ for ActiveMQ with an active/standby broker deployment across two Availability Zones.",
    "Replace the broker with Amazon SQS queues and Amazon SNS topics, and update the applications to the AWS SDK.",
    "Replace the broker with Amazon Kinesis Data Streams and rewrite producers and consumers with the KCL.",
    "Run ActiveMQ on EC2 instances in an Auto Scaling group across two AZs with EBS volumes for message storage."],
 a:[0],
 x:["Amazon MQ is a managed broker for ActiveMQ and RabbitMQ that supports JMS, AMQP, MQTT, STOMP, and OpenWire, so applications keep their messaging code, and an active/standby deployment fails over across AZs.",
    "SQS and SNS scale well, but moving from JMS, AMQP, and MQTT to the AWS SDK means rewriting the messaging code.",
    "Kinesis is a streaming service with a different programming model, so producers and consumers would have to be rewritten.",
    "Self-managed ActiveMQ keeps the code, but the company must patch it and build failover itself, and EBS volumes are tied to one AZ; it is not a managed broker."],
 ref:["d9e2","d9e3"], doc:"mq"},
{id:"m2-064", day:"mock", dom:3, tags:["Regions & AZs","EC2 instance types"],
 q:"A visual effects studio in Los Angeles wants its artists to use GPU-powered virtual workstations and render nodes on Amazon EC2 instead of buying new hardware. The applications are highly interactive, so the artists need single-digit-millisecond latency to the instances, which the nearest AWS Region cannot provide from the studio's location. The studio has no space for servers on site and does not want to install or host any hardware. Artists connect over the studio's fiber internet connection. Which solution meets these requirements?",
 o:["Run the instances in the nearest Region and route the artists' traffic through AWS Global Accelerator endpoints.",
    "Order an AWS Outposts rack for the studio and run the GPU instances on it inside the studio's own building.",
    "Run the instances in a subnet in the AWS Local Zone in Los Angeles that extends a VPC from the parent Region.",
    "Run the instances in an AWS Wavelength Zone so that traffic stays inside the mobile carrier's 5G network."],
 a:[2],
 x:["Global Accelerator improves the network path to a Region, but it cannot remove the physical distance to the Region, so latency stays above what the artists need.",
    "Outposts would deliver low latency, but it means hosting AWS hardware on site, which the studio has no space for and does not want.",
    "Local Zones place EC2 capacity, including GPU instances in some zones such as Los Angeles, close to large metropolitan areas for single-digit-millisecond latency, as an extension of a parent Region's VPC with nothing to host on site.",
    "Wavelength Zones place compute at the edge of communications service providers' networks and take inbound traffic from the carrier network, which suits devices on that carrier, not artists on the studio's fiber connection."],
 ref:["d10e3","d1w4","d1c6"], doc:"regions"},
{id:"m2-065", day:"mock", dom:4, tags:["Cost management tools"],
 q:"A company's monthly AWS spend varies widely across 60 accounts because of seasonal projects, so fixed budget thresholds either fire constantly or miss real problems. Last quarter a misconfigured ETL job ran up a large bill for two weeks before anyone noticed. Finance wants a daily alert about unusual spending by service and account, including the likely root cause, without maintaining thresholds or custom code. Which solution meets these requirements?",
 o:["Create AWS Budgets cost budgets for each account with alert thresholds that finance updates every month.",
    "Create CloudWatch billing alarms on estimated charges for each service with static thresholds and SNS alerts.",
    "Configure AWS Cost Anomaly Detection monitors for the accounts and services with a daily alert subscription.",
    "Export the Cost and Usage Report to S3 and build Athena queries and a Lambda function that flag large changes."],
 a:[2],
 x:["Budgets alert on fixed or forecasted thresholds that someone must keep updating, which is the approach that has already failed for this variable spend.",
    "Billing alarms use static thresholds on estimated charges, so they have the same false-alarm and missed-spike problems.",
    "Cost Anomaly Detection uses machine learning to learn normal spending patterns for each monitored account and service, flags anomalies with root cause analysis, and sends individual alerts or daily or weekly summaries.",
    "A custom pipeline on the Cost and Usage Report could detect changes, but it is custom code to build and maintain, which finance wants to avoid."],
 ref:["d11e2","d6w3","d1d1"], doc:"cost-anomaly"}
);
